params.command:
$ErrorActionPreference='SilentlyContinue'
$desk=[Environment]::GetFolderPath('Desktop')
$ws=New-Object -ComObject WScript.Shell
$links=Get-ChildItem $desk -Filter *.lnk | ForEach-Object {
  $s=$ws.CreateShortcut($_.FullName)
  if($_.Name -match 'MHW|Mod|Manager'){
    [pscustomobject]@{Name=$_.Name;Path=$_.FullName;Target=$s.TargetPath;Arguments=$s.Arguments;WorkingDirectory=$s.WorkingDirectory;IconLocation=$s.IconLocation}
  }
}
$procs=Get-CimInstance Win32_Process | Where-Object { $_.Name -match 'MHW|Mod|Manager' } | ForEach-Object {
  $p=$_
  $ver=$null
  if($p.ExecutablePath -and (Test-Path $p.ExecutablePath)){ $ver=(Get-Item $p.ExecutablePath).VersionInfo.ProductVersion }
  [pscustomobject]@{Pid=$p.ProcessId;Name=$p.Name;Exe=$p.ExecutablePath;Version=$ver;CommandLine=$p.CommandLine}
}
$cands=@()
$roots=@(
  "$env:LOCALAPPDATA\Programs",
  "$env:LOCALAPPDATA\MHW*",
  "$env:APPDATA",
  "$env:USERPROFILE\Desktop",
  "$env:USERPROFILE\OneDrive\Desktop",
  "$env:USERPROFILE\Downloads",
  "$env:USERPROFILE\local-ai-workspaces\mhw-mods"
)
foreach($r in $roots){
  Get-ChildItem -Path $r -Recurse -File -Filter *.exe -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'MHW|ModManager|ManualMod|Manager' } | ForEach-Object {
    $v=$_.VersionInfo
    $cands += [pscustomobject]@{Path=$_.FullName;ProductVersion=$v.ProductVersion;FileVersion=$v.FileVersion;LastWriteTime=$_.LastWriteTimeUtc}
  }
}
[pscustomobject]@{Desktop=$desk;Links=$links;Processes=$procs;Candidates=$cands} | ConvertTo-Json -Depth 5 -Compress
